// Add small goals shared by the generated booking variants before rendering the model.
function makeLabScenario(family='all',previous=''){
 let v,signature;
 do{v={family:family==='all'?labPick(['borrow','booking','repair']):family,context:labPick([0,1,2]),number:labPick([0,1,2]),extra:labPick([false,true])};signature=[v.family,v.context,v.number,Number(v.extra)].join('-');}while(signature===previous);
 const c=({borrow:labBorrow,booking:labBooking,repair:labRepair})[v.family](v);
 if(v.family==='booking'){c.uses.push(['ดูรายละเอียดการจอง',[0]],['เข้าสู่ระบบ',[1,2]]);}
 c.duration=75;c.signature=signature;c.family=v.family;c.variant=v;c.code='LAB-'+signature.toUpperCase();
 return c;
}
